package com.iceinventory.onhand;

import android.content.Context;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.Locale;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public final class ProfessionalCombinedXlsxWriter {
    private ProfessionalCombinedXlsxWriter(){}
    public static final class SourceRow { public final String sourceType,userName,fileName; public final int rows; public final long quantity; public SourceRow(String a,String b,String c,int d,long e){sourceType=a==null?"":a;userName=b==null?"":b;fileName=c==null?"":c;rows=d;quantity=e;} }
    public static final class CombinedRow { public final String barcode,description,price; public final long quantity; public CombinedRow(String a,String b,String c,long d){barcode=a==null?"":a;description=b==null?"":b;price=c==null?"":c;quantity=d;} }

    public static void write(Context context,OutputStream out,String report,String master,List<SourceRow> sources,List<CombinedRow> rows,long sourceTotal,long combinedTotal,boolean verified,Date when)throws IOException{
        if(when==null)when=new Date(); ZipOutputStream z=new ZipOutputStream(out);
        put(z,"[Content_Types].xml",types()); put(z,"_rels/.rels",rootRels()); put(z,"xl/workbook.xml",workbook()); put(z,"xl/_rels/workbook.xml.rels",bookRels()); put(z,"xl/styles.xml",styles());
        put(z,"xl/worksheets/sheet1.xml",verification(report,master,sources,rows.size(),sourceTotal,combinedTotal,verified,when)); put(z,"xl/worksheets/sheet2.xml",combined(report,master,rows,when)); put(z,"xl/worksheets/sheet3.xml",valuation(report,master,rows,when)); z.finish(); z.flush();
    }

    private static String verification(String report,String master,List<SourceRow> sources,int unique,long sourceTotal,long combinedTotal,boolean verified,Date when){
        String t=fmt(when); StringBuilder x=open(5); row(x,1,tc("A1","Ice Inventory LLC",1)); row(x,2,tc("A2","Combined Batch Verification & Reconciliation Report",1)); row(x,4,tc("A4","Report / Inventory",1)+tc("B4",report,0)); row(x,5,tc("A5","Master Report User",1)+tc("B5",master,0)); row(x,6,tc("A6","Created At",1)+tc("B6",t,0)); row(x,7,tc("A7","Verification Status",1)+tc("B7",verified?"PASS - VERIFIED":"FAIL - NOT VERIFIED",1));
        int totalRows=0; for(SourceRow s:sources) totalRows+=s.rows; row(x,9,tc("A9","Selected Source Files",1)+nc("B9",sources.size(),0)); row(x,10,tc("A10","Source Rows",1)+nc("B10",totalRows,0)); row(x,11,tc("A11","Combined Unique Barcodes",1)+nc("B11",unique,0)); row(x,12,tc("A12","Source Grand Total Quantity",1)+nc("B12",sourceTotal,0)); row(x,13,tc("A13","Combined Grand Total Quantity",1)+nc("B13",combinedTotal,0)); row(x,14,tc("A14","Difference",1)+nc("B14",combinedTotal-sourceTotal,0));
        row(x,16,tc("A16","Source Type",1)+tc("B16","User / Operator",1)+tc("C16","Source File",1)+tc("D16","Rows",1)+tc("E16","Quantity",1)); int r=17; for(SourceRow s:sources){row(x,r,tc("A"+r,s.sourceType,0)+tc("B"+r,s.userName,0)+tc("C"+r,s.fileName,0)+nc("D"+r,s.rows,0)+nc("E"+r,s.quantity,0));r++;}
        r++; row(x,r,tc("A"+r,"Formal Verification Note",1)); r++; row(x,r,tc("A"+r,"Ice Inventory LLC certifies that this report was generated by the designated Master Report User using the source files listed above. A PASS confirms computational reconciliation of the selected electronic source files: all selected files loaded, matching barcodes were consolidated, and source and combined grand totals match exactly. This verification does not independently certify the physical accuracy of the underlying inventory counts.",0)); r+=2; row(x,r,tc("A"+r,"Verification Method",1)); r++; row(x,r,tc("A"+r,"Files are validated by tab-delimited content, not by filename. Recognizable Barcode and Quantity headers are accepted. Headerless external files are also accepted when they use Quantity | Barcode | Description | Price. PASS requires every selected file to load successfully and source and combined grand totals to match exactly.",0)); r+=2; row(x,r,tc("A"+r,"FINAL RESULT",1)+tc("B"+r,verified?"PASS - ALL SELECTED SOURCE QUANTITIES INCLUDED AND TOTALS MATCH":"FAIL - RECONCILIATION NOT VERIFIED",1)); return close(x,null);
    }

    private static String combined(String report,String master,List<CombinedRow> rows,Date when){
        StringBuilder x=open(4); row(x,1,tc("A1","Ice Inventory LLC - Combined Inventory",1)); row(x,2,tc("A2","Report: "+clean(report)+" | Master Report User: "+clean(master)+" | Created: "+fmt(when),0)); row(x,4,tc("A4","Quantity",1)+tc("B4","Barcode",1)+tc("C4","Description",1)+tc("D4","Price",1)); int r=5; for(CombinedRow a:rows){double p=money(a.price); row(x,r,nc("A"+r,a.quantity,0)+tc("B"+r,a.barcode,0)+tc("C"+r,a.description,0)+(Double.isNaN(p)?tc("D"+r,a.price,0):dc("D"+r,p,2))); r++;} return close(x,"A4:D"+Math.max(4,r-1));
    }

    private static String valuation(String report,String master,List<CombinedRow> rows,Date when){
        StringBuilder x=open(5); row(x,1,tc("A1","Ice Inventory LLC - Total Inventory Valuation",1)); row(x,2,tc("A2","Report: "+clean(report)+" | Master Report User: "+clean(master)+" | Created: "+fmt(when),0)); row(x,3,tc("A3","Extended Value = Quantity x Price. Missing or non-numeric prices are valued at $0.00 and listed in the review count.",0)); row(x,4,tc("A4","Quantity",1)+tc("B4","Barcode",1)+tc("C4","Description",1)+tc("D4","Price",1)+tc("E4","Extended Value",1)); int r=5,missing=0; double grand=0; for(CombinedRow a:rows){double p=money(a.price); if(Double.isNaN(p)){p=0;missing++;} double ext=a.quantity*p; grand+=ext; row(x,r,nc("A"+r,a.quantity,0)+tc("B"+r,a.barcode,0)+tc("C"+r,a.description,0)+dc("D"+r,p,2)+dc("E"+r,ext,2)); r++;} int last=r-1; r++; row(x,r,tc("D"+r,"Grand Total Inventory Value",1)+dc("E"+r,grand,3)); r++; row(x,r,tc("D"+r,"Lines Requiring Price Review",1)+nc("E"+r,missing,0)); return close(x,"A4:E"+Math.max(4,last));
    }

    private static StringBuilder open(int cols){StringBuilder x=new StringBuilder(12000);x.append("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"/></sheetViews><cols>");double[] w={14,22,48,16,20};for(int i=0;i<cols;i++)x.append("<col min=\"").append(i+1).append("\" max=\"").append(i+1).append("\" width=\"").append(w[i]).append("\" customWidth=\"1\"/>");x.append("</cols><sheetData>");return x;}
    private static String close(StringBuilder x,String filter){x.append("</sheetData>");if(filter!=null)x.append("<autoFilter ref=\"").append(filter).append("\"/>");x.append("</worksheet>");return x.toString();}
    private static void row(StringBuilder x,int n,String cells){x.append("<row r=\"").append(n).append("\">").append(cells).append("</row>");}
    private static String tc(String ref,String v,int s){return "<c r=\""+ref+"\" t=\"inlineStr\""+(s>0?" s=\""+s+"\"":"")+"><is><t xml:space=\"preserve\">"+xml(v)+"</t></is></c>";}
    private static String nc(String ref,long v,int s){return "<c r=\""+ref+"\""+(s>0?" s=\""+s+"\"":"")+"><v>"+v+"</v></c>";}
    private static String dc(String ref,double v,int s){return "<c r=\""+ref+"\""+(s>0?" s=\""+s+"\"":"")+"><v>"+String.format(Locale.US,"%.2f",v)+"</v></c>";}
    private static String fmt(Date d){return new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).format(d);} private static double money(String s){String v=clean(s);if(v.isEmpty())return Double.NaN;try{return Double.parseDouble(v.replace("$","").replace(",","").trim());}catch(Exception e){return Double.NaN;}}
    private static String clean(String s){return s==null?"":s.replace('\t',' ').replace('\r',' ').replace('\n',' ').trim();}
    private static String xml(String s){String v=clean(s);StringBuilder b=new StringBuilder(v.length());for(int i=0;i<v.length();i++){char c=v.charAt(i);if(c>=0x20||c=='\t'||c=='\n'||c=='\r')b.append(c);}return b.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
    private static void put(ZipOutputStream z,String n,String c)throws IOException{z.putNextEntry(new ZipEntry(n));z.write(c.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
    private static String types(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet2.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet3.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/></Types>";}
    private static String rootRels(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>";}
    private static String workbook(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Verification\" sheetId=\"1\" r:id=\"rId1\"/><sheet name=\"Combined Inventory\" sheetId=\"2\" r:id=\"rId2\"/><sheet name=\"Inventory Valuation\" sheetId=\"3\" r:id=\"rId3\"/></sheets></workbook>";}
    private static String bookRels(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet2.xml\"/><Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet3.xml\"/><Relationship Id=\"rId4\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>";}
    private static String styles(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><numFmts count=\"1\"><numFmt numFmtId=\"164\" formatCode=\"$#,##0.00\"/></numFmts><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><sz val=\"11\"/><name val=\"Calibri\"/></font></fonts><fills count=\"2\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill></fills><borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"4\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyFont=\"1\"/><xf numFmtId=\"164\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/><xf numFmtId=\"164\" fontId=\"1\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyFont=\"1\" applyNumberFormat=\"1\"/></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>";}
}
